'use client';

import { useEffect, useState } from 'react';
import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import { 
  BuildingOfficeIcon, 
  ArchiveBoxIcon,
  ShoppingBagIcon,
  ArrowTrendingUpIcon,
  ExclamationTriangleIcon,
  EyeIcon,
  ArrowDownTrayIcon,
  DocumentChartBarIcon
} from '@heroicons/react/24/outline';
import { api } from '@/lib/api';
import { formatCurrency, formatNumber, cn } from '@/lib/utils';
import { DashboardSummaryResponse, BranchResponse, StockLevelResponse } from '@/types';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';

export default function DashboardReportsPage() {
  const [summary, setSummary] = useState<DashboardSummaryResponse | null>(null);
  const [branches, setBranches] = useState<BranchResponse[]>([]);
  const [selectedBranchId, setSelectedBranchId] = useState<string>('all');
  const [loading, setLoading] = useState(true);
  const [stock, setStock] = useState<StockLevelResponse[]>([]);
  const [loadingStock, setLoadingStock] = useState(false);

  useEffect(() => {
    const fetchInitialData = async () => {
      try {
        setLoading(true);
        const [summaryRes, branchesRes] = await Promise.all([
          api.dashboard.getSummary(),
          api.branches.getAll()
        ]);

        if (summaryRes.success) setSummary(summaryRes.data);
        if (branchesRes.success) setBranches(branchesRes.data);
      } catch (error) {
        console.error('Error fetching initial data:', error);
      } finally {
        setLoading(false);
      }
    };
    fetchInitialData();
  }, []);

  useEffect(() => {
    const fetchPreviewData = async () => {
      if (selectedBranchId === 'all') {
        setStock([]);
        return;
      }
      try {
        setLoadingStock(true);
        const res = await api.stock.getByBranch(selectedBranchId);
        if (res.success) {
          setStock(res.data || []);
        }
      } catch (error) {
        console.error('Error fetching stock for preview:', error);
      } finally {
        setLoadingStock(false);
      }
    };
    fetchPreviewData();
  }, [selectedBranchId]);

  const currentBranchSummary = selectedBranchId === 'all' 
    ? null 
    : summary?.branchSummaries.find(b => b.branchId === selectedBranchId);

  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6 max-w-7xl mx-auto">
          {/* Header */}
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <div>
              <h1 className="text-2xl font-black text-primary tracking-tight flex items-center gap-2">
                <DocumentChartBarIcon className="w-8 h-8 text-primary/40" />
                Report Preview
              </h1>
              <p className="text-sm font-medium text-text-secondary">Live data preview for branch inventory and status</p>
            </div>
            
            <div className="flex items-center gap-3 bg-card p-2 rounded-2xl border border-divider/40 shadow-sm">
              <span className="text-xs font-black text-text-secondary uppercase tracking-widest ml-2">Select Branch:</span>
              <Select value={selectedBranchId} onValueChange={setSelectedBranchId}>
                <SelectTrigger className="w-[240px] border-none bg-surface/50 font-bold focus:ring-0">
                  <SelectValue placeholder="Select Branch" />
                </SelectTrigger>
                <SelectContent className="rounded-xl border-divider/60">
                  <SelectItem value="all" className="font-bold">All Branches Overview</SelectItem>
                  {branches.map(branch => (
                    <SelectItem key={branch.id} value={branch.id} className="font-medium">{branch.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          {loading ? (
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              <div className="lg:col-span-1 space-y-6">
                <div className="h-64 bg-surface animate-pulse rounded-3xl" />
                <div className="h-48 bg-surface animate-pulse rounded-3xl" />
              </div>
              <div className="lg:col-span-2 h-[600px] bg-surface animate-pulse rounded-3xl" />
            </div>
          ) : (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
              
              {/* Left Column: Stats & Summary */}
              <div className="lg:col-span-4 space-y-6">
                <Card className="border-none shadow-xl shadow-primary/5 bg-gradient-to-br from-card to-surface/30 overflow-hidden relative">
                  <div className="absolute top-0 right-0 p-8 opacity-[0.03]">
                    <BuildingOfficeIcon className="w-32 h-32" />
                  </div>
                  <CardHeader>
                    <CardTitle className="text-xs font-black text-text-secondary uppercase tracking-[0.2em]">
                      {selectedBranchId === 'all' ? 'Consolidated Overview' : 'Branch Performance'}
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-6 relative z-10">
                    <div className="grid grid-cols-2 gap-4">
                      <div className="p-4 rounded-2xl bg-primary/5 border border-primary/10">
                        <p className="text-[10px] font-black text-primary/60 uppercase mb-1">Stock Value</p>
                        <p className="text-xl font-black text-primary">
                          {formatCurrency(selectedBranchId === 'all' ? summary?.totalInventoryValue || 0 : currentBranchSummary?.totalStockValue || 0)}
                        </p>
                      </div>
                      <div className="p-4 rounded-2xl bg-success/5 border border-success/10">
                        <p className="text-[10px] font-black text-success/60 uppercase mb-1">Total SKUs</p>
                        <p className="text-xl font-black text-success">
                          {selectedBranchId === 'all' ? summary?.totalProducts : currentBranchSummary?.totalProducts || 0}
                        </p>
                      </div>
                      <div className="p-4 rounded-2xl bg-info/5 border border-info/10">
                        <p className="text-[10px] font-black text-info/60 uppercase mb-1">Total Units</p>
                        <p className="text-xl font-black text-info">
                          {formatNumber(selectedBranchId === 'all' ? summary?.branchSummaries.reduce((a, b) => a + b.totalUnits, 0) || 0 : currentBranchSummary?.totalUnits || 0)}
                        </p>
                      </div>
                      <div className="p-4 rounded-2xl bg-error/5 border border-error/10">
                        <p className="text-[10px] font-black text-error/60 uppercase mb-1">Low Stock</p>
                        <p className="text-xl font-black text-error">
                          {selectedBranchId === 'all' ? summary?.totalLowStockItems : currentBranchSummary?.lowStockCount || 0}
                        </p>
                      </div>
                    </div>

                    <div className="pt-4 border-t border-divider/40">
                      <div className="flex items-center justify-between mb-4">
                        <h4 className="text-sm font-black text-primary">Status Distribution</h4>
                        <Badge variant="outline" className="text-[10px] border-divider/60">Live</Badge>
                      </div>
                      <div className="space-y-3">
                        <div className="flex justify-between items-center text-sm font-bold">
                          <span className="text-text-secondary flex items-center gap-2">
                            <div className="w-2 h-2 rounded-full bg-success" />
                            Healthy Stock
                          </span>
                          <span className="text-primary">
                            {selectedBranchId === 'all' 
                              ? (summary?.totalProducts || 0) - (summary?.totalLowStockItems || 0) - (summary?.totalOutOfStockItems || 0)
                              : (currentBranchSummary?.totalProducts || 0) - (currentBranchSummary?.lowStockCount || 0) - (currentBranchSummary?.outOfStockCount || 0)}
                          </span>
                        </div>
                        <div className="flex justify-between items-center text-sm font-bold text-error">
                          <span className="flex items-center gap-2">
                            <div className="w-2 h-2 rounded-full bg-error" />
                            Out of Stock
                          </span>
                          <span>{selectedBranchId === 'all' ? summary?.totalOutOfStockItems : currentBranchSummary?.outOfStockCount || 0}</span>
                        </div>
                      </div>
                    </div>
                  </CardContent>
                </Card>

                {selectedBranchId === 'all' && (
                  <Card className="border-none shadow-xl shadow-primary/5 bg-card overflow-hidden">
                    <CardHeader className="bg-primary/5 border-b border-divider/40">
                      <CardTitle className="text-sm font-black text-primary flex items-center gap-2">
                        <BuildingOfficeIcon className="w-4 h-4" />
                        Branch Ranking
                      </CardTitle>
                    </CardHeader>
                    <CardContent className="p-0">
                      <div className="divide-y divide-divider/40">
                        {summary?.branchSummaries
                          .sort((a, b) => b.totalStockValue - a.totalStockValue)
                          .map((b, i) => (
                            <div key={b.branchId} className="p-4 flex items-center justify-between hover:bg-surface/50 transition-colors">
                              <div className="flex items-center gap-3">
                                <span className="text-xs font-black text-text-secondary/40">#{i+1}</span>
                                <div>
                                  <p className="text-sm font-black text-primary">{b.branchName}</p>
                                  <p className="text-[10px] font-bold text-text-secondary uppercase">{b.branchType}</p>
                                </div>
                              </div>
                              <p className="text-sm font-black text-success">{formatCurrency(b.totalStockValue)}</p>
                            </div>
                          ))}
                      </div>
                    </CardContent>
                  </Card>
                )}
              </div>

              {/* Right Column: Preview Content */}
              <div className="lg:col-span-8">
                <Card className="border-none shadow-2xl shadow-primary/5 bg-card flex flex-col h-[calc(100vh-200px)] min-h-[600px] overflow-hidden">
                  <CardHeader className="shrink-0 border-b border-divider/40 bg-surface/30 px-6 py-4 flex flex-row items-center justify-between">
                    <div>
                      <CardTitle className="text-lg font-black text-primary tracking-tight">
                        {selectedBranchId === 'all' ? 'All Branches Activity' : `${currentBranchSummary?.branchName} Inventory Preview`}
                      </CardTitle>
                      <p className="text-xs font-medium text-text-secondary">Viewing current stock levels and valuations</p>
                    </div>
                    <div className="flex gap-2">
                      <Button variant="outline" size="sm" className="h-8 text-[10px] font-black uppercase tracking-widest border-divider/60">
                        <EyeIcon className="w-3.5 h-3.5 mr-1.5" />
                        Full View
                      </Button>
                      <Button variant="outline" size="sm" className="h-8 text-[10px] font-black uppercase tracking-widest border-divider/60">
                        <ArrowDownTrayIcon className="w-3.5 h-3.5 mr-1.5" />
                        Export Preview
                      </Button>
                    </div>
                  </CardHeader>
                  <CardContent className="flex-1 overflow-y-auto custom-scrollbar p-0">
                    {selectedBranchId === 'all' ? (
                      <div className="p-8 text-center space-y-4 max-w-md mx-auto mt-20">
                        <div className="w-20 h-20 bg-primary/5 rounded-3xl flex items-center justify-center mx-auto">
                          <BuildingOfficeIcon className="w-10 h-10 text-primary/30" />
                        </div>
                        <div>
                          <h3 className="text-lg font-black text-primary">Consolidated Network View</h3>
                          <p className="text-sm text-text-secondary font-medium mt-2 leading-relaxed">
                            You are currently viewing the aggregated stats for all <b>{summary?.totalBranches}</b> branches. 
                            Select a specific branch to preview its detailed inventory report.
                          </p>
                        </div>
                      </div>
                    ) : (
                      <div className="divide-y divide-divider/40">
                        {loadingStock ? (
                          <div className="p-12 text-center space-y-4">
                            <div className="w-8 h-8 border-4 border-primary/20 border-t-primary rounded-full animate-spin mx-auto" />
                            <p className="text-xs font-black text-text-secondary uppercase tracking-[0.2em] animate-pulse">Loading Inventory...</p>
                          </div>
                        ) : stock.length > 0 ? (
                          <table className="w-full text-left border-collapse">
                            <thead className="sticky top-0 bg-card z-10 shadow-sm">
                              <tr className="border-b border-divider/60">
                                <th className="px-6 py-4 text-[10px] font-black text-text-secondary uppercase tracking-widest">Product</th>
                                <th className="px-6 py-4 text-[10px] font-black text-text-secondary uppercase tracking-widest">SKU</th>
                                <th className="px-6 py-4 text-[10px] font-black text-text-secondary uppercase tracking-widest text-center">On Hand</th>
                                <th className="px-6 py-4 text-[10px] font-black text-text-secondary uppercase tracking-widest text-right">Value</th>
                              </tr>
                            </thead>
                            <tbody className="divide-y divide-divider/40">
                              {stock.map((item) => (
                                <tr key={item.id} className="hover:bg-surface/50 transition-colors">
                                  <td className="px-6 py-4">
                                    <p className="text-sm font-black text-primary">{item.productName}</p>
                                    <p className="text-[10px] font-bold text-text-secondary uppercase">{item.category || 'Uncategorized'}</p>
                                  </td>
                                  <td className="px-6 py-4">
                                    <code className="text-[10px] font-bold bg-surface px-2 py-1 rounded text-primary/70">{item.productSku}</code>
                                  </td>
                                  <td className="px-6 py-4 text-center">
                                    <div className="flex flex-col items-center">
                                      <span className={cn(
                                        "text-sm font-black",
                                        item.quantityOnHand <= item.minimumStockThreshold ? "text-error" : "text-primary"
                                      )}>
                                        {item.quantityOnHand}
                                      </span>
                                      {item.quantityOnHand <= item.minimumStockThreshold && (
                                        <Badge variant="error" className="text-[8px] h-4 font-black mt-1">LOW</Badge>
                                      )}
                                    </div>
                                  </td>
                                  <td className="px-6 py-4 text-right">
                                    <p className="text-sm font-black text-success">{formatCurrency(item.quantityOnHand * item.sellingPrice)}</p>
                                    <p className="text-[10px] font-bold text-text-secondary">{formatCurrency(item.sellingPrice)}/ea</p>
                                  </td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        ) : (
                          <div className="p-20 text-center space-y-4">
                            <ArchiveBoxIcon className="w-16 h-16 text-text-secondary opacity-20 mx-auto" />
                            <p className="text-sm font-bold text-text-secondary">No stock data found for this branch.</p>
                          </div>
                        )}
                      </div>
                    )}
                  </CardContent>
                  <CardHeader className="shrink-0 border-t border-divider/40 bg-surface/30 px-6 py-3 flex flex-row items-center justify-between">
                    <p className="text-[10px] font-black text-text-secondary uppercase tracking-widest">
                      Last Updated: {new Date().toLocaleTimeString()}
                    </p>
                    <div className="flex items-center gap-4 text-[10px] font-black text-text-secondary uppercase tracking-widest">
                      <div className="flex items-center gap-1.5">
                        <div className="w-2 h-2 rounded-full bg-success" />
                        Healthy
                      </div>
                      <div className="flex items-center gap-1.5">
                        <div className="w-2 h-2 rounded-full bg-error" />
                        At Risk
                      </div>
                    </div>
                  </CardHeader>
                </Card>
              </div>
            </div>
          )}
        </div>
      </Layout>
    </AuthGuard>
  );
}
